package com.punjab.oms.ar.service.finance;
import com.punjab.oms.ar.ArApplication;import com.punjab.oms.ar.base.*;
import com.punjab.oms.ar.domain.dto.finance.*;import com.punjab.oms.ar.enums.*;
import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import java.math.BigDecimal;import java.time.LocalDate;import java.nio.file.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;
/** scripts/test-mysql-invoice：开票关联完整事务验证。 @author Punjab */
@SpringBootTest(classes=ArApplication.class,webEnvironment=SpringBootTest.WebEnvironment.NONE) @ActiveProfiles("pre")
@EnabledIfSystemProperty(named="ar.invoice.real",matches="true") @EnabledIfSystemProperty(named="ar.invoice.real.commit",matches="true")
class InvoiceRealTest {
 @DynamicPropertySource static void config(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:mysql://127.0.0.1:13306/oms_ar_test");p.add("spring.datasource.username",()->"oms_ar");p.add("spring.datasource.password",()->System.getenv("AR_TEST_PASSWORD"));}
 @Autowired InvoiceService invoices;@Autowired ReceiptService receipts;@Autowired ReceivableService receivables;@Autowired SettlementService settlements;@Autowired JdbcTemplate jdbc;
 private String key(){return UUID.randomUUID().toString();} private BigDecimal n(String v){return new BigDecimal(v);}
 private void actor(){CurrentUser.set(new CurrentUser.Identity("offset-test",Set.of(1L),Set.of("ar:create","ar:read","ar:settle","ar:reverse","ar:invoice:write","ar:receipt:create")));}
 @BeforeEach void setup()throws Exception{assertThat(jdbc.queryForObject("SELECT DATABASE()",String.class)).isEqualTo("oms_ar_test");
  for(String name:List.of("V001__ar_core.sql","V002__ar_audit.sql","V011__ar_outbox.sql","V003__ar_receipt.sql","V013__ar_cash_account.sql","V015__ar_cash_receipt_lot.sql","V004__ar_settlement.sql","V005__ar_adjustment_link.sql","V008__ar_invoice.sql","V009__ar_exchange_basis.sql","V010__ar_source_guard.sql")){var file=Path.of("../scratch/dbddl/"+name);if(Files.exists(file))for(String sql:Files.readString(file).split(";"))if(!sql.isBlank())jdbc.execute(sql);}actor();}
 @AfterEach void clear(){CurrentUser.clear();}
 private long line(AmountType type,String amount,Long group,Long original){
  long doc=receivables.create(new ReceivableCreateRequest(key(),1L,1L,"CNY","TAX_ADJUSTMENT",LocalDate.now(),null,"test",List.of(new ReceivableCreateRequest.Line("A",group,type,n(amount),type==AmountType.OUTPUT_TAX?n("0.13"):null,type==AmountType.OUTPUT_TAX?n("100"):null,null,original))));
  return jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,doc);
 }
 private long group(long line){return jdbc.queryForObject("SELECT group_id FROM oms_ar_line WHERE id=?",Long.class,line);}
 private BigDecimal open(long line){return jdbc.queryForObject("SELECT open_amount FROM oms_ar_line WHERE id=?",BigDecimal.class,line);}

 private InvoicePreviewRequest preview(InvoiceKind kind,Long original,String amount,long line,BigDecimal rate,Long allocation){return new InvoicePreviewRequest(1L,1L,"CNY",kind,original,n(amount),List.of(new InvoicePreviewRequest.Line("1",line,n(amount),rate,allocation)));}
 private InvoiceRegisterRequest registration(InvoicePreviewRequest request){var view=invoices.preview(request);assertThat(view).isNotNull();return new InvoiceRegisterRequest(key(),"TEST",key(),key(),LocalDate.now(),request,view.fingerprint(),"invoice");}
 private BigDecimal invoiced(long line){return jdbc.queryForObject("SELECT invoiced_amount FROM oms_ar_line WHERE id=?",BigDecimal.class,line);}
 private long originalAllocation(long invoice){return jdbc.queryForObject("SELECT id FROM oms_ar_invoice_allocation WHERE invoice_id=?",Long.class,invoice);}
 @Test @DisplayName("已结清应收可开票，登记重放及撤销不改变收款")void blueAndReverse(){long price=line(AmountType.PRINCIPAL,"100",null,null);long receipt=receipts.create(new ReceiptCreateRequest(key(),1L,1L,"CNY",n("100"),LocalDate.now(),"TEST",key(),"paid"));var settle=new SettlementPreviewRequest(1L,receipt,n("100"),List.of(group(price)),AllocationStrategy.GROUP_TAX_FIRST);settlements.confirm(new SettlementConfirmRequest(key(),settle,settlements.preview(settle).fingerprint(),"paid"));var request=registration(preview(InvoiceKind.BLUE,null,"100",price,null,null));long id=invoices.register(request);assertThat(id).isPositive();assertThat(invoices.register(request)).isEqualTo(id);assertThat(invoiced(price)).isEqualByComparingTo("100");assertThat(open(price)).isEqualByComparingTo("0");var reverse=new InvoiceReverseRequest(key(),1L,id,"undo");assertThat(invoices.reverse(reverse)).isEqualTo(id);assertThat(invoices.reverse(reverse)).isEqualTo(id);assertThat(invoiced(price)).isEqualByComparingTo("0");assertThat(open(price)).isEqualByComparingTo("0");}
 @Test @DisplayName("行额度充足仍不能越过调整后的组共享额度")void sharedCapacity(){long price=line(AmountType.PRINCIPAL,"100",null,null);line(AmountType.PRINCIPAL,"-20",null,price);assertThatThrownBy(()->invoices.preview(preview(InvoiceKind.BLUE,null,"100",price,null,null))).isInstanceOf(ServiceException.class);invoices.register(registration(preview(InvoiceKind.BLUE,null,"80",price,null,null)));assertThatThrownBy(()->invoices.preview(preview(InvoiceKind.BLUE,null,"20",price,null,null))).isInstanceOf(ServiceException.class);}
 @Test @DisplayName("拟开票税率与原应收不同必须先调整")void rate(){long tax=line(AmountType.OUTPUT_TAX,"13",null,null);assertThatThrownBy(()->invoices.preview(preview(InvoiceKind.BLUE,null,"13",tax,n("0.09"),null))).isInstanceOf(ServiceException.class);invoices.register(registration(preview(InvoiceKind.BLUE,null,"13",tax,n("0.13"),null)));assertThat(invoiced(tax)).isEqualByComparingTo("13");}
 @Test @DisplayName("原蓝字有有效红字依赖时不能撤销")void redDependency(){long price=line(AmountType.PRINCIPAL,"100",null,null),blue=invoices.register(registration(preview(InvoiceKind.BLUE,null,"100",price,null,null))),credit=line(AmountType.PRINCIPAL,"-20",null,price);long red=invoices.register(registration(preview(InvoiceKind.RED,blue,"-20",credit,null,originalAllocation(blue))));assertThat(invoiced(credit)).isEqualByComparingTo("-20");assertThatThrownBy(()->invoices.reverse(new InvoiceReverseRequest(key(),1L,blue,"blocked"))).isInstanceOf(ServiceException.class);invoices.reverse(new InvoiceReverseRequest(key(),1L,red,"undo red"));invoices.reverse(new InvoiceReverseRequest(key(),1L,blue,"undo blue"));assertThat(invoiced(price)).isEqualByComparingTo("0");assertThat(invoiced(credit)).isEqualByComparingTo("0");}
 @Test @DisplayName("多笔红字合计不能超过原分配")void redLimit(){long price=line(AmountType.PRINCIPAL,"100",null,null),blue=invoices.register(registration(preview(InvoiceKind.BLUE,null,"100",price,null,null))),allocation=originalAllocation(blue),first=line(AmountType.PRINCIPAL,"-60",null,price);invoices.register(registration(preview(InvoiceKind.RED,blue,"-60",first,null,allocation)));long second=line(AmountType.PRINCIPAL,"-60",null,price);assertThatThrownBy(()->invoices.preview(preview(InvoiceKind.RED,blue,"-60",second,null,allocation))).isInstanceOf(ServiceException.class);invoices.register(registration(preview(InvoiceKind.RED,blue,"-40",second,null,allocation)));assertThat(invoices.detail(new com.punjab.oms.ar.domain.query.finance.InvoiceDetailQuery(blue,1L)).allocations().getFirst().redAvailableAmount()).isEqualByComparingTo("0");}

 @Test @DisplayName("相同业务组不同应收并发登记不能越过共享额度")void concurrentShared()throws Exception{
  long first=line(AmountType.PRINCIPAL,"100",null,null),second=line(AmountType.PRINCIPAL,"100",group(first),null);line(AmountType.PRINCIPAL,"-100",null,first);
  var a=registration(preview(InvoiceKind.BLUE,null,"80",first,null,null));var b=registration(preview(InvoiceKind.BLUE,null,"80",second,null,null));var start=new java.util.concurrent.CountDownLatch(2);
  try(var executor=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=executor.submit(()->race(start,()->invoices.register(a)));var two=executor.submit(()->race(start,()->invoices.register(b)));assertThat(List.of(one.get(10,java.util.concurrent.TimeUnit.SECONDS),two.get(10,java.util.concurrent.TimeUnit.SECONDS))).containsExactlyInAnyOrder(true,false);}
  assertThat(invoiced(first).add(invoiced(second))).isEqualByComparingTo("80");
 }
 private boolean race(java.util.concurrent.CountDownLatch start,java.util.concurrent.Callable<Long> action)throws Exception{actor();try{start.countDown();if(!start.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("timeout");try{action.call();return true;}catch(ServiceException expected){return false;}}finally{CurrentUser.clear();}}
 @Test @DisplayName("红字登记与原蓝字撤销竞争只能成功一项")void redReverseRace()throws Exception{
  long price=line(AmountType.PRINCIPAL,"100",null,null),blue=invoices.register(registration(preview(InvoiceKind.BLUE,null,"100",price,null,null))),credit=line(AmountType.PRINCIPAL,"-20",null,price);var red=registration(preview(InvoiceKind.RED,blue,"-20",credit,null,originalAllocation(blue)));var start=new java.util.concurrent.CountDownLatch(2);
  try(var executor=java.util.concurrent.Executors.newFixedThreadPool(2)){var one=executor.submit(()->race(start,()->invoices.register(red)));var two=executor.submit(()->race(start,()->invoices.reverse(new InvoiceReverseRequest(key(),1L,blue,"race reverse"))));boolean redDone=one.get(10,java.util.concurrent.TimeUnit.SECONDS),reversed=two.get(10,java.util.concurrent.TimeUnit.SECONDS);assertThat(redDone).isNotEqualTo(reversed);assertThat(invoiced(price)).isEqualByComparingTo(redDone?"100":"0");assertThat(invoiced(credit)).isEqualByComparingTo(redDone?"-20":"0");}
 }
 @Test @DisplayName("新增调整使旧预览失效即使剩余额仍足够")void stale(){long price=line(AmountType.PRINCIPAL,"100",null,null);var request=registration(preview(InvoiceKind.BLUE,null,"40",price,null,null));line(AmountType.PRINCIPAL,"-20",null,price);assertThatThrownBy(()->invoices.register(request)).isInstanceOf(ServiceException.class);assertThat(invoiced(price)).isEqualByComparingTo("0");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_operation_request WHERE request_key=?",Integer.class,request.requestKey())).isZero();}
 @Test @DisplayName("外部发票来源重复不重复记账且回滚新请求")void duplicateSource(){long first=line(AmountType.PRINCIPAL,"10",null,null),second=line(AmountType.PRINCIPAL,"10",null,null);var old=registration(preview(InvoiceKind.BLUE,null,"10",first,null,null));invoices.register(old);var fresh=registration(preview(InvoiceKind.BLUE,null,"10",second,null,null));var duplicate=new InvoiceRegisterRequest(fresh.requestKey(),old.sourceSystem(),old.sourceId(),fresh.invoiceNo(),fresh.invoiceDate(),fresh.preview(),fresh.expectedFingerprint(),fresh.reason());assertThatThrownBy(()->invoices.register(duplicate)).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);assertThat(invoiced(second)).isEqualByComparingTo("0");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_operation_request WHERE request_key=?",Integer.class,fresh.requestKey())).isZero();}
 @Test @DisplayName("开票流水失败时单头、分配和已开票额一起回滚")void journalFailure(){long price=line(AmountType.PRINCIPAL,"100",null,null);var base=registration(preview(InvoiceKind.BLUE,null,"50",price,null,null));String reason="FAIL-"+key(),constraint="reject_invoice_"+key().replace("-","");jdbc.execute("ALTER TABLE oms_ar_lifecycle_event ADD CONSTRAINT "+constraint+" CHECK(reason IS NULL OR reason<>'"+reason+"')");try{var request=new InvoiceRegisterRequest(base.requestKey(),base.sourceSystem(),base.sourceId(),base.invoiceNo(),base.invoiceDate(),base.preview(),base.expectedFingerprint(),reason);assertThatThrownBy(()->invoices.register(request)).isInstanceOf(RuntimeException.class);assertThat(invoiced(price)).isEqualByComparingTo("0");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_invoice WHERE source_system=? AND source_id=?",Integer.class,base.sourceSystem(),base.sourceId())).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_invoice_allocation WHERE receivable_line_id=?",Integer.class,price)).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM oms_ar_operation_request WHERE request_key=?",Integer.class,base.requestKey())).isZero();}finally{jdbc.execute("ALTER TABLE oms_ar_lifecycle_event DROP CHECK "+constraint);}}
 @Test @DisplayName("撤销流水失败时原关联仍有效")void reverseFailure(){long price=line(AmountType.PRINCIPAL,"100",null,null),id=invoices.register(registration(preview(InvoiceKind.BLUE,null,"50",price,null,null)));String reason="FAIL-"+key(),constraint="reject_invoice_reverse_"+key().replace("-","");jdbc.execute("ALTER TABLE oms_ar_lifecycle_event ADD CONSTRAINT "+constraint+" CHECK(reason IS NULL OR reason<>'"+reason+"')");try{assertThatThrownBy(()->invoices.reverse(new InvoiceReverseRequest(key(),1L,id,reason))).isInstanceOf(RuntimeException.class);assertThat(invoiced(price)).isEqualByComparingTo("50");assertThat(jdbc.queryForObject("SELECT status FROM oms_ar_invoice WHERE id=?",String.class,id)).isEqualTo("ACTIVE");}finally{jdbc.execute("ALTER TABLE oms_ar_lifecycle_event DROP CHECK "+constraint);}}
 @Test @DisplayName("撤销早期蓝字不改变后续分配")void reverseEarlier(){long price=line(AmountType.PRINCIPAL,"100",null,null),first=invoices.register(registration(preview(InvoiceKind.BLUE,null,"30",price,null,null))),second=invoices.register(registration(preview(InvoiceKind.BLUE,null,"40",price,null,null)));invoices.reverse(new InvoiceReverseRequest(key(),1L,first,"first only"));assertThat(invoiced(price)).isEqualByComparingTo("40");assertThat(invoices.detail(new com.punjab.oms.ar.domain.query.finance.InvoiceDetailQuery(second,1L)).header().status()).isEqualTo("ACTIVE");}
 @Test @DisplayName("一条红字行合并引用多条原分配可登记并准确撤销")void consolidated(){long price=line(AmountType.PRINCIPAL,"10",null,null);var blueRequest=new InvoicePreviewRequest(1L,1L,"CNY",InvoiceKind.BLUE,null,n("10"),List.of(new InvoicePreviewRequest.Line("1",price,n("5"),null,null),new InvoicePreviewRequest.Line("2",price,n("5"),null,null)));long blue=invoices.register(registration(blueRequest)),credit=line(AmountType.PRINCIPAL,"-10",null,price);var original=invoices.detail(new com.punjab.oms.ar.domain.query.finance.InvoiceDetailQuery(blue,1L)).allocations();var redRequest=new InvoicePreviewRequest(1L,1L,"CNY",InvoiceKind.RED,blue,n("-10"),List.of(new InvoicePreviewRequest.Line("1",credit,n("-5"),null,original.get(0).id()),new InvoicePreviewRequest.Line("1",credit,n("-5"),null,original.get(1).id())));long red=invoices.register(registration(redRequest));assertThat(invoiced(credit)).isEqualByComparingTo("-10");assertThat(invoices.detail(new com.punjab.oms.ar.domain.query.finance.InvoiceDetailQuery(red,1L)).allocations()).hasSize(2);invoices.reverse(new InvoiceReverseRequest(key(),1L,red,"undo consolidated"));assertThat(invoiced(credit)).isEqualByComparingTo("0");}
 @Test @DisplayName("指定原行不能借用同组另一行的蓝字分配")void wrongOriginal(){long first=line(AmountType.PRINCIPAL,"100",null,null),second=line(AmountType.PRINCIPAL,"100",group(first),null),blue=invoices.register(registration(preview(InvoiceKind.BLUE,null,"100",second,null,null))),credit=line(AmountType.PRINCIPAL,"-20",null,first);assertThatThrownBy(()->invoices.preview(preview(InvoiceKind.RED,blue,"-20",credit,null,originalAllocation(blue)))).isInstanceOf(ServiceException.class);long independent=line(AmountType.PRINCIPAL,"-20",null,null);invoices.register(registration(preview(InvoiceKind.RED,blue,"-20",independent,null,originalAllocation(blue))));assertThat(invoiced(independent)).isEqualByComparingTo("-20");}
 @Test @DisplayName("写权限独立校验且无需额外查询权限")void permission(){long price=line(AmountType.PRINCIPAL,"100",null,null);var request=preview(InvoiceKind.BLUE,null,"10",price,null,null);CurrentUser.set(new CurrentUser.Identity("readonly",Set.of(1L),Set.of("ar:read")));assertThatThrownBy(()->invoices.preview(request)).isInstanceOf(RuntimeException.class);CurrentUser.set(new CurrentUser.Identity("invoice-writer",Set.of(1L),Set.of("ar:invoice:write")));long id=invoices.register(registration(request));assertThat(id).isPositive();assertThatThrownBy(()->invoices.detail(new com.punjab.oms.ar.domain.query.finance.InvoiceDetailQuery(id,1L))).isInstanceOf(RuntimeException.class);}
 @Test @DisplayName("总额和单行累计额度都需校验")void amountChecks(){long first=line(AmountType.PRINCIPAL,"100",null,null);line(AmountType.PRINCIPAL,"100",group(first),null);assertThatThrownBy(()->invoices.preview(new InvoicePreviewRequest(1L,1L,"CNY",InvoiceKind.BLUE,null,n("120"),List.of(new InvoicePreviewRequest.Line("1",first,n("60"),null,null),new InvoicePreviewRequest.Line("2",first,n("60"),null,null))))).isInstanceOf(ServiceException.class);assertThatThrownBy(()->invoices.preview(new InvoicePreviewRequest(1L,1L,"CNY",InvoiceKind.BLUE,null,n("11"),List.of(new InvoicePreviewRequest.Line("1",first,n("10"),null,null))))).isInstanceOf(ServiceException.class);}
 @Autowired com.punjab.oms.ar.config.InvoiceProperties invoiceProperties;
 @Test @DisplayName("旧税率负数冲回并登记红字后以新税率应收开票")void adjustedRate(){
  long old=line(AmountType.OUTPUT_TAX,"13",null,null),blue=invoices.register(registration(preview(InvoiceKind.BLUE,null,"13",old,n("0.13"),null))),credit=line(AmountType.OUTPUT_TAX,"-13",null,old);
  long doc=receivables.create(new ReceivableCreateRequest(key(),1L,1L,"CNY","TAX_ADJUSTMENT",LocalDate.now(),null,"new rate",List.of(new ReceivableCreateRequest.Line("A",group(old),AmountType.OUTPUT_TAX,n("9"),n("0.09"),n("100"),null,null))));
  long replacement=jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,doc);
  invoices.register(registration(preview(InvoiceKind.RED,blue,"-13",credit,n("0.13"),originalAllocation(blue))));
  invoices.register(registration(preview(InvoiceKind.BLUE,null,"9",replacement,n("0.09"),null)));
  assertThat(invoiced(old).add(invoiced(credit)).add(invoiced(replacement))).isEqualByComparingTo("9");
  assertThat(jdbc.queryForObject("SELECT tax_rate FROM oms_ar_line WHERE id=?",BigDecimal.class,old)).isEqualByComparingTo("0.13");
  assertThat(open(old)).isEqualByComparingTo("13");assertThat(open(credit)).isEqualByComparingTo("-13");
 }
 @Test @DisplayName("汇率差异默认禁开且显式开启后仍校验依据")void exchangeSwitch(){
  long doc=receivables.create(new ReceivableCreateRequest(key(),1L,1L,"CNY","EXCHANGE_DIFFERENCE",LocalDate.now(),null,"fx",List.of(new ReceivableCreateRequest.Line("A",null,AmountType.PRINCIPAL,n("20"),null,null,null,null,new ReceivableCreateRequest.ExchangeBasis("USD",n("100"),n("7.1"),n("7.3"),ExchangeRateDirection.SETTLEMENT_PER_ORIGINAL)))));
  long fx=jdbc.queryForObject("SELECT id FROM oms_ar_line WHERE document_id=?",Long.class,doc);var request=preview(InvoiceKind.BLUE,null,"20",fx,null,null);
  assertThat(invoiceProperties.isExchangeDifferenceEnabled()).isFalse();assertThatThrownBy(()->invoices.preview(request)).isInstanceOf(ServiceException.class);
  invoiceProperties.setExchangeDifferenceEnabled(true);try{invoices.register(registration(request));assertThat(invoiced(fx)).isEqualByComparingTo("20");assertThat(open(fx)).isEqualByComparingTo("20");}finally{invoiceProperties.setExchangeDifferenceEnabled(false);}
 }
 @Test @DisplayName("开票预览及原发票不可跨客户主体或币种")void scope(){
  long price=line(AmountType.PRINCIPAL,"100",null,null);var lines=List.of(new InvoicePreviewRequest.Line("1",price,n("10"),null,null));
  assertThatThrownBy(()->invoices.preview(new InvoicePreviewRequest(1L,2L,"CNY",InvoiceKind.BLUE,null,n("10"),lines))).isInstanceOf(ServiceException.class);
  assertThatThrownBy(()->invoices.preview(new InvoicePreviewRequest(1L,1L,"USD",InvoiceKind.BLUE,null,n("10"),lines))).isInstanceOf(ServiceException.class);
  assertThatThrownBy(()->invoices.preview(new InvoicePreviewRequest(2L,1L,"CNY",InvoiceKind.BLUE,null,n("10"),lines))).isInstanceOf(RuntimeException.class);
 }

}
